  SELECT (SELECT total_deduplicated FROM search_runs WHERE search_run_id = p_search_run_id);
$$ LANGUAGE sql STABLE;

-- get_search_runs_failed_listings
-- Helper function: Get FailedListings from SearchRuns by SearchRunId
-- Used for join-free cross-table references in aggregations

CREATE OR REPLACE FUNCTION get_search_runs_failed_listings(p_search_run_id TEXT)
RETURNS INTEGER AS $$
  SELECT (SELECT failed_listings FROM search_runs WHERE search_run_id = p_search_run_id);
$$ LANGUAGE sql STABLE;

-- calc_score_results_name
-- Field: ScoreResults.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_score_results_name(p_score_result_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT(calc_score_results_job_listing_name(p_score_result_id), ' - ', calc_score_results_search_run_name(p_score_result_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_score_results_final_score
-- Field: ScoreResults.FinalScore
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_score_results_final_score(p_score_result_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (CASE WHEN COALESCE((SELECT is_disqualified FROM score_results WHERE score_result_id = p_score_result_id), FALSE) THEN (0)::text ELSE (GREATEST(0, (COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT fit_score FROM score_results WHERE score_result_id = p_score_result_id)) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT archetype_score FROM score_results WHERE score_result_id = p_score_result_id)) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT history_score FROM score_results WHERE score_result_id = p_score_result_id)) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT comp_score FROM score_results WHERE score_result_id = p_score_result_id)) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT culture_score FROM score_results WHERE score_result_id = p_score_result_id)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT negative_score FROM score_results WHERE score_result_id = p_score_result_id)) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0))))::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_decisions_job_listing_name
-- Field: Decisions.JobListingName
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: Name from related JobListings


CREATE OR REPLACE FUNCTION calc_decisions_job_listing_name(p_decision_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT name::text FROM job_listings WHERE job_listing_id = (SELECT job_listing FROM decisions WHERE decision_id = p_decision_id));
$$ LANGUAGE sql STABLE;

-- calc_decisions_company
-- Field: Decisions.Company
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: Company from related JobListings


CREATE OR REPLACE FUNCTION calc_decisions_company(p_decision_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT company::text FROM job_listings WHERE job_listing_id = (SELECT job_listing FROM decisions WHERE decision_id = p_decision_id));
$$ LANGUAGE sql STABLE;

-- calc_decisions_board
-- Field: Decisions.Board
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: JobBoard from related JobListings


CREATE OR REPLACE FUNCTION calc_decisions_board(p_decision_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT job_board::text FROM job_listings WHERE job_listing_id = (SELECT job_listing FROM decisions WHERE decision_id = p_decision_id));
$$ LANGUAGE sql STABLE;

-- calc_decisions_name
-- Field: Decisions.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_decisions_name(p_decision_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT(UPPER((SELECT NULLIF(verdict, '') FROM decisions WHERE decision_id = p_decision_id)), ': ', calc_decisions_job_listing_name(p_decision_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_decisions_is_scoring_signal
-- Field: Decisions.IsScoringSignal
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_decisions_is_scoring_signal(p_decision_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (CASE WHEN COALESCE((SELECT NULLIF(verdict, '') FROM decisions WHERE decision_id = p_decision_id), '') = 'yes' THEN TRUE ELSE FALSE END)::boolean;
$$ LANGUAGE sql STABLE;

